package com.drivique.api.service;import com.drivique.api.dto.*;import com.drivique.api.exception.*;import com.drivique.api.model.*;import com.drivique.api.repository.*;import java.time.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.multipart.MultipartFile;
@Service public class IncidentService{private final IncidentReportRepository reports;private final IncidentResponseRepository responses;private final UserRepository users;private final VehicleRepository vehicles;private final ReservationRepository reservations;private final FileStorageService storage;public IncidentService(IncidentReportRepository reports,IncidentResponseRepository responses,UserRepository users,VehicleRepository vehicles,ReservationRepository reservations,FileStorageService storage){this.reports=reports;this.responses=responses;this.users=users;this.vehicles=vehicles;this.reservations=reservations;this.storage=storage;}@Transactional public UUID create(IncidentRequestDTO in,String email){User user=current(email);Reservation reservation=in.reservationId()==null?null:reservations.findById(in.reservationId()).orElseThrow(()->new ResourceNotFoundException("Reserva no encontrada"));if(reservation!=null&&!reservation.getCustomer().getId().equals(user.getId()))throw new ResourceNotFoundException("Reserva no encontrada");Vehicle vehicle=in.vehicleId()==null?(reservation==null?null:reservation.getVehicle()):vehicles.findById(in.vehicleId()).orElseThrow(()->new ResourceNotFoundException("Vehículo no encontrado"));int year=Year.now().getValue();String prefix="INC-"+year+"-";String code=prefix+String.format("%04d",reports.countByIncidentCodeStartingWith(prefix)+1);return reports.saveAndFlush(new IncidentReport(code,vehicle,reservation,user,in.priority(),in.subject().trim(),in.description().trim())).getId();}@Transactional public void respond(UUID id,String message,MultipartFile attachment,String email){IncidentReport report=reports.findById(id).orElseThrow(()->new ResourceNotFoundException("Incidencia no encontrada"));User user=current(email);boolean owner=report.getReporter().getId().equals(user.getId());boolean staff=user.getRoles().stream().anyMatch(r->Set.of("EMPLOYEE","BRANCH_ADMIN","ADMIN","SUPER_ADMIN","AGENT").contains(r.getCode()));if(!owner&&!staff)throw new ResourceNotFoundException("Incidencia no encontrada");String url=attachment==null?null:storage.storeFile(attachment,"support/incidents");responses.saveAndFlush(new IncidentResponse(report,user,message.trim(),url));}@Transactional public void status(UUID id,IncidentStatusRequestDTO input){IncidentReport report=reports.findById(id).orElseThrow(()->new ResourceNotFoundException("Incidencia no encontrada"));report.setStatus(input.status());}private User current(String e){return users.findByEmailIgnoreCaseAndDeletedAtIsNull(e).orElseThrow(()->new ResourceNotFoundException("Usuario no encontrado"));}}
